#define main block_auth_embedded_main
#include "block_auth.cpp"
#undef BLOCK_AUTH_NO_MAIN
#undef main
#include <chrono>
#include <sstream>
#include <unordered_set>

struct GCfg { std::string data="../dataset/sift", out="ivf_granularity_results.csv"; int base=100000,nq=50,k=100,iters=6; std::vector<int> nlists{128,256,512,1024}, probes; };
static std::vector<int> ints(const std::string&s){std::vector<int>v;std::stringstream z(s);std::string x;while(std::getline(z,x,','))v.push_back(std::stoi(x));return v;}
static GCfg args(int ac,char**av){GCfg c;for(int i=1;i<ac;++i){std::string a=av[i];auto v=[&](){if(++i==ac)throw std::runtime_error("missing value");return std::string(av[i]);};if(a=="--dataset")c.data=v();else if(a=="--output")c.out=v();else if(a=="--base")c.base=std::stoi(v());else if(a=="--queries")c.nq=std::stoi(v());else if(a=="--k")c.k=std::stoi(v());else if(a=="--iters")c.iters=std::stoi(v());else if(a=="--nlists")c.nlists=ints(v());else if(a=="--nprobes")c.probes=ints(v());else throw std::runtime_error("unknown option "+a);}return c;}
static std::vector<std::vector<int>> exact_gt(const Matrix&xb,const Matrix&xq,int k){std::vector<std::vector<int>>g(xq.rows());for(size_t qi=0;qi<xq.rows();++qi){std::priority_queue<std::pair<float,int>>h;for(size_t id=0;id<xb.rows();++id){float z=l2(xq[qi],xb[id],xb.d);if((int)h.size()<k)h.push({z,(int)id});else if(z<h.top().first){h.pop();h.push({z,(int)id});}}while(!h.empty())g[qi].push_back(h.top().second),h.pop();}return g;}
static std::pair<std::vector<int>,std::vector<int>> split2(const Matrix&x,const std::vector<int>&ids,int iters){if(ids.size()<2)return {ids,{}};int a=ids[0],b=a;float far=-1;for(int id:ids){float z=l2(x[a],x[id],x.d);if(z>far)far=z,b=id;}std::vector<float>ca(x[a],x[a]+x.d),cb(x[b],x[b]+x.d);std::vector<int>A,B;for(int it=0;it<iters;++it){A.clear();B.clear();for(int id:ids)(l2(x[id],ca.data(),x.d)<=l2(x[id],cb.data(),x.d)?A:B).push_back(id);if(A.empty()||B.empty()){A.assign(ids.begin(),ids.begin()+ids.size()/2);B.assign(ids.begin()+ids.size()/2,ids.end());break;}std::fill(ca.begin(),ca.end(),0);std::fill(cb.begin(),cb.end(),0);for(int id:A)for(int j=0;j<x.d;++j)ca[j]+=x[id][j];for(int id:B)for(int j=0;j<x.d;++j)cb[j]+=x[id][j];for(int j=0;j<x.d;++j){ca[j]/=A.size();cb[j]/=B.size();}}return {std::move(A),std::move(B)};}
static std::vector<std::vector<int>> hkmeans(const Matrix&x,int K,int iters){std::vector<std::vector<int>>ls(1);ls[0].resize(x.rows());std::iota(ls[0].begin(),ls[0].end(),0);while((int)ls.size()<K){auto it=std::max_element(ls.begin(),ls.end(),[](auto&a,auto&b){return a.size()<b.size();});auto p=split2(x,*it,iters);*it=std::move(p.first);ls.push_back(std::move(p.second));if((ls.size()&(ls.size()-1))==0)std::cerr<<" leaves="<<ls.size()<<'\n';}return ls;}
// Query-trace-independent capacity-balanced hierarchical k-means.
static std::pair<std::vector<int>,std::vector<int>> split2_balanced(const Matrix&x,const std::vector<int>&ids,int iters){if(ids.size()<2)return {ids,{}};int a=ids[0],b=a;float far=-1;for(int id:ids){float z=l2(x[a],x[id],x.d);if(z>far)far=z,b=id;}std::vector<float>ca(x[a],x[a]+x.d),cb(x[b],x[b]+x.d);std::vector<std::pair<float,int>>rank(ids.size());const size_t cut=ids.size()/2;for(int it=0;it<std::max(1,iters);++it){for(size_t z=0;z<ids.size();++z)rank[z]={l2(x[ids[z]],ca.data(),x.d)-l2(x[ids[z]],cb.data(),x.d),ids[z]};std::sort(rank.begin(),rank.end(),[](const auto&u,const auto&v){return u.first==v.first?u.second<v.second:u.first<v.first;});std::fill(ca.begin(),ca.end(),0);std::fill(cb.begin(),cb.end(),0);for(size_t z=0;z<rank.size();++z){auto&c=z<cut?ca:cb;for(int j=0;j<x.d;++j)c[j]+=x[rank[z].second][j];}for(float&v:ca)v/=cut;for(float&v:cb)v/=(rank.size()-cut);}std::vector<int>A,B;A.reserve(cut);B.reserve(ids.size()-cut);for(size_t z=0;z<rank.size();++z)(z<cut?A:B).push_back(rank[z].second);return {std::move(A),std::move(B)};}
static std::vector<std::vector<int>> hkmeans_balanced(const Matrix&x,int K,int iters){std::vector<std::vector<int>>ls(1);ls[0].resize(x.rows());std::iota(ls[0].begin(),ls[0].end(),0);while((int)ls.size()<K){auto it=std::max_element(ls.begin(),ls.end(),[](const auto&a,const auto&b){return a.size()<b.size();});auto p=split2_balanced(x,*it,iters);*it=std::move(p.first);ls.push_back(std::move(p.second));if((ls.size()&(ls.size()-1))==0)std::cerr<<" balanced leaves="<<ls.size()<<'\n';}return ls;}
#ifndef IVF_GRANULARITY_NO_MAIN
int main(int ac,char**av)try{auto c=args(ac,av);Matrix xb=fvecs(c.data+"/sift_base.fvecs",c.base),xq=fvecs(c.data+"/sift_query.fvecs",c.nq);auto gt=exact_gt(xb,xq,c.k);SQ4 sq(xb);std::ofstream o(c.out);o<<"nlist,nprobe,recall,avg_visited,avg_exact,flat_sq4_vo_bytes,raw_vector_bytes,list_exact_merkle_bytes,routing_merkle_bytes,total_vo_bytes,quant_reduction_vs_raw,query_time_ms,vo_generation_time_ms\n";for(int K:c.nlists){std::cerr<<"Training hierarchical IVF nlist="<<K<<"...\n";auto ls=hkmeans(xb,K,c.iters);auto cs=centers(xb,ls);std::vector<int>ps;if(c.probes.empty()){for(int p=1;p<=K;p*=2)ps.push_back(p);}else{for(int p:c.probes)if(p<=K)ps.push_back(p);}for(int np:ps){uint64_t vis=0,ex=0,hits=0;double local_auth=0,routing_auth=0,query_ns=0,vo_ns=0;for(size_t qi=0;qi<xq.rows();++qi){auto query_start=std::chrono::steady_clock::now();std::vector<int>ord(K);std::iota(ord.begin(),ord.end(),0);std::partial_sort(ord.begin(),ord.begin()+np,ord.end(),[&](int a,int b){return l2(xq[qi],cs[a].data(),xb.d)<l2(xq[qi],cs[b].data(),xb.d);});std::priority_queue<std::pair<float,int>>top;for(int z=0;z<np;++z)for(int id:ls[ord[z]]){float d=l2(xq[qi],xb[id],xb.d);++vis;if((int)top.size()<c.k)top.push({d,id});else if(d<top.top().first){top.pop();top.push({d,id});}}if((int)top.size()<c.k)continue;float tau=std::sqrt(top.top().first);auto query_end=std::chrono::steady_clock::now();query_ns+=std::chrono::duration<double,std::nano>(query_end-query_start).count();std::unordered_set<int>ans;while(!top.empty())ans.insert(top.top().second),top.pop();for(int id:gt[qi])if(ans.count(id))++hits;auto vo_start=std::chrono::steady_clock::now();for(int z=0;z<np;++z){std::vector<int>opened;for(size_t p=0;p<ls[ord[z]].size();++p)if(sq.lb(xq[qi],ls[ord[z]][p])<=tau){opened.push_back((int)p);++ex;}local_auth+=proof_count(ls[ord[z]].size(),opened)*32.0;}std::vector<int>selected(ord.begin(),ord.begin()+np);routing_auth+=proof_count(K,selected)*32.0+np*8.0;auto vo_end=std::chrono::steady_clock::now();vo_ns+=std::chrono::duration<double,std::nano>(vo_end-vo_start).count();}double nq=xq.rows(),rec=hits/(nq*c.k),flat=vis*72.0/nq+ex*512.0/nq,raw=vis*512.0/nq,local=local_auth/nq,routing=routing_auth/nq,total=flat+local+routing;o<<K<<','<<np<<','<<rec<<','<<vis/nq<<','<<ex/nq<<','<<flat<<','<<raw<<','<<local<<','<<routing<<','<<total<<','<<1-total/raw<<','<<query_ns/nq/1e6<<','<<vo_ns/nq/1e6<<'\n';std::cout<<K<<' '<<np<<' '<<std::fixed<<std::setprecision(4)<<rec<<' '<<vis/nq<<' '<<total/1024<<" KiB query="<<query_ns/nq/1e6<<" ms vo="<<vo_ns/nq/1e6<<" ms\n";}}return 0;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}
#endif
